import * as json from "std/json"
import * as console from "std/console"
export function test(): null {
  let t: table = json.parse("{\"a\":\"\\u00E9\",\"b\":\"\\u4E2D\"}");
  let a: string = t.a;
  let b: string = t.b;
  if (a !== "é") { console.log("luajit-std-json-bmp-escape-decode-a-mismatch"); return; }
  if (b !== "中") { console.log("luajit-std-json-bmp-escape-decode-b-mismatch"); return; }
  console.log("luajit-std-json-bmp-escape-decode-ok");
}

