import * as json from "std/json"
import * as console from "std/console"
export function test(): null {
  let t: table = json.parse("{\"q\":\"\\u0022\",\"b\":\"\\u005C\"}");
  let q: string = t.q;
  let b: string = t.b;
  if (q !== "\"") { console.log("luajit-std-json-escaped-quote-backslash-decode-q-mismatch"); return; }
  if (b !== "\\") { console.log("luajit-std-json-escaped-quote-backslash-decode-b-mismatch"); return; }
  console.log("luajit-std-json-escaped-quote-backslash-decode-ok");
}

import * as json from "std/json"
import * as str from "std/string"
import * as console from "std/console"
export function test(): null {
  let sup: string = "𝄞";
  let t: table = { v: sup };
  let encoded: string = json.stringify(t);
  if (!str.contains(encoded, sup)) { console.log("luajit-std-json-supplementary-roundtrip-stringify-lost-raw-bytes"); return; }
  if (str.contains(encoded, "\\uD834")) { console.log("luajit-std-json-supplementary-roundtrip-stringify-escaped-pair"); return; }
  let back: table = json.parse(encoded);
  let v: string = back.v;
  if (v !== sup) { console.log("luajit-std-json-supplementary-roundtrip-mismatch"); return; }
  console.log("luajit-std-json-supplementary-roundtrip-ok");
}

import * as json from "std/json"
import * as str from "std/string"
import * as console from "std/console"
export function test(): null {
  let t: table = json.parse("{\"s\":\"\\u00E9\\u4E2D\\uD834\\uDD1E\"}");
  let s: string = t.s;
  let n: int = str.length(s);
  if (n !== 3) { console.log("luajit-std-json-scalar-length-crosscheck-bad-count"); return; }
  console.log("luajit-std-json-scalar-length-crosscheck-ok");
}

