import * as json from "std/json"
export function test(): null {
  let ok: boolean = true;
  try {
    json.parse("{\"v\":\"\\u12\"}");
    ok = false;
  } catch (e) {
    if (e.code !== "E8001") { ok = false; }
  }
  try {
    json.parse("{\"v\":\"\\uZZZZ\"}");
    ok = false;
  } catch (e) {
    if (e.code !== "E8001") { ok = false; }
  }
  if (!ok) {
    throw { code: "E9999", message: "malformed unicode escape accepted or mis-coded" };
  }
  json.parse("{\"v\":\"\\uZZZZ\"}");
}

import * as json from "std/json"
export function test(): null {
  let ok: boolean = true;
  try {
    json.parse("{\"v\":\"\\x41\"}");
    ok = false;
  } catch (e) {
    if (e.code !== "E8001") { ok = false; }
  }
  try {
    json.parse("{\"v\":\"\\'\"}");
    ok = false;
  } catch (e) {
    if (e.code !== "E8001") { ok = false; }
  }
  if (!ok) {
    throw { code: "E9999", message: "unknown escape accepted or mis-coded" };
  }
  json.parse("{\"v\":\"\\x41\"}");
}

